package io.knowledgebrain.integration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import jakarta.servlet.http.Cookie;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class GitHubSyncHistoryApiTest {
 GitHubStore store=mock(GitHubStore.class);GitHubClient remote=mock(GitHubClient.class);SpaceAuthorizationClient auth=mock(SpaceAuthorizationClient.class);UUID space,repo,actor;GitHubController api;SimpleMeterRegistry metrics;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();repo=ids.next();actor=ids.next();when(auth.authorize(eq(space),any(),eq(false),anyString())).thenReturn(actor);metrics=new SimpleMeterRegistry();api=new GitHubController(store,remote,auth,metrics,"https://localhost:8443");}
 MockHttpServletRequest req(){var r=new MockHttpServletRequest("GET","/api/spaces/"+space+"/github/repositories/"+repo+"/syncs");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));return r;}
 @Test void eachPageFreshlyAuthorizesPrivateReadAndNeverContactsGithub(){var page=new GitHubStore.SyncPage(List.of(),null);when(store.syncs(space,repo,null,20)).thenReturn(page);assertEquals(page,api.syncs(space.toString(),repo.toString(),req()).getBody());var next=req();next.addParameter("before","7");next.addParameter("limit","100");when(store.syncs(space,repo,7L,100)).thenReturn(page);var result=api.syncs(space.toString(),repo.toString(),next);assertEquals("no-store",result.getHeaders().getCacheControl());assertEquals(page,result.getBody());verify(auth,times(2)).authorize(eq(space),eq("a".repeat(43)),eq(false),anyString());assertEquals(2,metrics.counter("brain.integration.github.reads","type","sync-history").count());verifyNoInteractions(remote);reset(store);when(auth.authorize(eq(space),any(),eq(false),anyString())).thenThrow(new ResponseStatusException(HttpStatus.NOT_FOUND));assertThrows(ResponseStatusException.class,()->api.syncs(space.toString(),repo.toString(),req()));verifyNoInteractions(store,remote);}
 @Test void strictQueriesBodyAndCredentialsRejectBeforeAnySourceRead(){for(String[] entry:new String[][]{{"before","0"},{"before","-1"},{"before","1.0"},{"before","9223372036854775808"},{"limit","101"},{"after",repo.toString()},{"state","ACTIVE"},{"actorId",actor.toString()}}){var request=req();request.addParameter(entry[0],entry[1]);assertThrows(ResponseStatusException.class,()->api.syncs(space.toString(),repo.toString(),request));}var duplicate=req();duplicate.addParameter("before","7","6");assertThrows(ResponseStatusException.class,()->api.syncs(space.toString(),repo.toString(),duplicate));var body=req();body.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->api.syncs(space.toString(),repo.toString(),body));var insecure=req();insecure.setSecure(false);assertThrows(ResponseStatusException.class,()->api.syncs(space.toString(),repo.toString(),insecure));var cookies=req();cookies.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));assertThrows(ResponseStatusException.class,()->api.syncs(space.toString(),repo.toString(),cookies));verifyNoInteractions(store,remote);}
}
